import sys
input = sys.stdin.readline

def two_smallest(a, b, c, d):
    if c < a:
        a, b, c, d = c, d, a, b
    return a, min(b, c)

n, q = map(int, input().split())
a = list(map(int, input().split()))
ops = [list(map(int, input().split())) for _ in range(q)]

size = 1
while size < n:
    size *= 2
inf = 1 << 62
m1 = [inf] * (2 * size)
m2 = [inf] * (2 * size)
for i in range(n):
    m1[size + i] = a[i]
for v in range(size - 1, 0, -1):
    m1[v], m2[v] = two_smallest(m1[2 * v], m2[2 * v], m1[2 * v + 1], m2[2 * v + 1])
out = []
for kind, x, y in ops:
    if kind == 1:
        v = size + x - 1
        m1[v] = y
        v //= 2
        while v:
            m1[v], m2[v] = two_smallest(m1[2 * v], m2[2 * v], m1[2 * v + 1], m2[2 * v + 1])
            v //= 2
    else:
        lo = size + x - 1
        hi = size + y
        ra, rb = inf, inf
        while lo < hi:
            if lo & 1:
                ra, rb = two_smallest(ra, rb, m1[lo], m2[lo])
                lo += 1
            if hi & 1:
                hi -= 1
                ra, rb = two_smallest(ra, rb, m1[hi], m2[hi])
            lo //= 2
            hi //= 2
