import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static long[] twoSmallest(long a, long b, long c, long d) {
        if (c < a) {
            long t = a;
            a = c;
            c = t;
            t = b;
            b = d;
            d = t;
        }
        return new long[] {a, Math.min(b, c)};
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long q = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());
        long[][] ops = new long[(int) q][3];
        for (int i = 0; i < ops.length; i++) {
            for (int j = 0; j < ops[i].length; j++) {
                ops[i][j] = Long.parseLong(next());
            }
        }

        int size = 1;
        while (size < n) size *= 2;
        long inf = 1L << 62;
        long[] m1 = new long[2 * size];
        long[] m2 = new long[2 * size];
        Arrays.fill(m1, inf);
        Arrays.fill(m2, inf);
        for (int i = 0; i < n; i++) m1[size + i] = a[i];
        for (int v = size - 1; v >= 1; v--) {
            long[] p = twoSmallest(m1[2 * v], m2[2 * v], m1[2 * v + 1], m2[2 * v + 1]);
            m1[v] = p[0];
            m2[v] = p[1];
        }
        StringBuilder out = new StringBuilder();
        for (int k = 0; k < q; k++) {
            long kind = ops[k][0];
            int x = (int) ops[k][1];
            long y = ops[k][2];
            if (kind == 1) {
                int v = size + x - 1;
                m1[v] = y;
                for (v /= 2; v >= 1; v /= 2) {
                    long[] p = twoSmallest(m1[2 * v], m2[2 * v], m1[2 * v + 1], m2[2 * v + 1]);
                    m1[v] = p[0];
                    m2[v] = p[1];
                }
            } else {
                int lo = size + x - 1, hi = size + (int) y;
                long ra = inf, rb = inf;
                while (lo < hi) {
                    if ((lo & 1) == 1) {
                        long[] p = twoSmallest(ra, rb, m1[lo], m2[lo]);
                        ra = p[0];
                        rb = p[1];
                        lo++;
                    }
                    if ((hi & 1) == 1) {
                        --hi;
                        long[] p = twoSmallest(ra, rb, m1[hi], m2[hi]);
                        ra = p[0];
                        rb = p[1];
                    }
                    lo /= 2;
                    hi /= 2;
                }
                if (out.length() > 0) out.append(" ");
                out.append(ra + rb);
            }
        }
        System.out.println(out);
    }
}
